script:
country_event = {
	id = focus.95
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		is_country_type = default
		NAND = {
			has_country_flag = energy_storage_1000
			has_country_flag = mineral_storage_1000
			has_country_flag = food_storage_1000
			has_country_flag = alloys_storage_1000
		}
		if = {
			limit = {
				country_uses_consumer_goods = yes
			}
			NOT = { has_country_flag = consumer_goods_storage_1000 }
		}
		if = {
			limit = {
				is_nomadic = yes
			}
			NAND = {
				has_country_flag = operational_reserves_low
				has_country_flag = operational_reserves_high
			}
		}
	}

	immediate = {
		if = { # Energy Credits
			limit = {
				NOT = { has_country_flag = energy_storage_1000 }
				resource_stockpile_compare = {
					resource = energy
					value >= 1000
				}
			}
			set_country_flag = energy_storage_1000
		}
		if = { # Minerals
			limit = {
				NOT = { has_country_flag = mineral_storage_1000 }
				resource_stockpile_compare = {
					resource = minerals
					value >= 1000
				}
			}
			set_country_flag = mineral_storage_1000
		}
		if = { # Food - Settled Empires
			limit = {
				NOT = { has_country_flag = food_storage_1000 }
				resource_stockpile_compare = {
					resource = food
					value >= 1000
				}
			}
			set_country_flag = food_storage_1000
		}
		if = { # Food - Nomadic Empires
			limit = {
				NOT = { has_country_flag = food_storage_3000 }
				resource_stockpile_compare = {
					resource = food
					value >= 3000
				}
			}
			set_country_flag = food_storage_3000
		}
		if = { # Consumer Goods - Settled Empires
			limit = {
				NOT = { has_country_flag = consumer_goods_storage_1000 }
				resource_stockpile_compare = {
					resource = consumer_goods
					value >= 1000
				}
			}
			set_country_flag = consumer_goods_storage_1000
		}
		if = { # Consumer Goods - Nomadic Empires
			limit = {
				NOT = { has_country_flag = consumer_goods_storage_3000 }
				resource_stockpile_compare = {
					resource = consumer_goods
					value >= 3000
				}
			}
			set_country_flag = consumer_goods_storage_3000
		}
		if = { # Alloys
			limit = {
				NOT = { has_country_flag = alloys_storage_1000 }
				resource_stockpile_compare = {
					resource = alloys
					value >= 1000
				}
			}
			set_country_flag = alloys_storage_1000
		}
		if = { # Operational Reserves Low - Nomadic Empires
			limit = {
				is_nomadic = yes
				NOT = { has_country_flag = operational_reserves_low }
				any_situation = {
					is_situation_type = situation_nomad_economy
					nomad_in_reserve_crisis = yes
				}
			}
			set_country_flag = operational_reserves_low
		}
		if = { # Operational Reserves High - Nomadic Empires
			limit = {
				is_nomadic = yes
				NOT = { has_country_flag = operational_reserves_high }
				any_situation = {
					is_situation_type = situation_nomad_economy
					current_stage = situation_nomad_economy_stage_3_thriving
				}
			}
			set_country_flag = operational_reserves_high
		}
	}
}

